// Keep only rows received today, then build a summary message.
const rows = $input.all().map(i => i.json);
const today = new Date().toISOString().slice(0, 10);
const todays = rows.filter(r => String(r.Received || '').slice(0, 10) === today);

const total = todays.length;
const booked = todays.filter(r => String(r.Booked).toLowerCase() === 'true').length;
const urgent = todays.filter(r => String(r.Urgency).toLowerCase() === 'urgent');
const callbacks = todays.filter(r => String(r.Booked).toLowerCase() !== 'true');

const business = (todays[0] && todays[0].Business) || 'your business';
const ownerPhone = $env.DEFAULT_OWNER_PHONE || '';

let text = `\uD83D\uDCCA ${business} \u2014 today's calls\n` +
  `Total: ${total} | Booked: ${booked} | To call back: ${callbacks.length}`;
if (urgent.length) {
  text += `\n\u26A0 ${urgent.length} urgent:`;
  urgent.slice(0, 5).forEach(r => { text += `\n\u2022 ${r.Name} ${r.Phone} \u2014 ${r.Reason}`; });
}
if (callbacks.length) {
  text += `\n\nCall back:`;
  callbacks.slice(0, 8).forEach(r => { text += `\n\u2022 ${r.Name} ${r.Phone} \u2014 ${r.Reason}`; });
}

return [{ json: { ownerPhone, summary: text, total } }];
